INSERT INTO rewards (reward_id, reward_name, reward_description, access_link, access_info, cost_points, img_url, is_active, reward_category) VALUES (12, 'CS50: Introduction to Computer Science', 'Harvard''s renowned introductory CS course. Learn programming fundamentals, algorithms, and data structures with professor David J. Malan.', 'https://cs50.harvard.edu/x/', 'Your enrollment code is: CS50X-4TNV-QK82. Use it at cs50.harvard.edu/x to access the full course materials and certificate. This code expires in 90 days.', 3500, 'https://pll.harvard.edu/sites/default/files/styles/16_9_large/public/course/CS50x_pll.png?itok=AxciDjWM', TRUE, 'course');
INSERT INTO rewards (reward_id, reward_name, reward_description, access_link, access_info, cost_points, img_url, is_active, reward_category) VALUES (13, 'Hack The Box VIP+ — 1 Month', '1-month VIP+ subscription on Hack The Box. Access exclusive machines, advanced labs, and premium cybersecurity training content.', 'https://www.hackthebox.com/', 'Your redemption code is: HTBVIP-9X2KAM4PQR37. Activate it at hackthebox.com/redeem. Valid for 30 days from first use.', 4500, 'https://www.hackthebox.com/storage/blog/AexAar28OIVOhpHO02l3RhedGaiixu4Q.jpg', TRUE, 'voucher');
INSERT INTO rewards (reward_id, reward_name, reward_description, access_link, access_info, cost_points, img_url, is_active, reward_category) VALUES (14, 'Udemy Course Voucher — €20', '€20 Udemy credit for any course of your choice. Expand your skills in technology, business, or personal development.', 'https://www.udemy.com/', 'Your Udemy gift code is: GIFT-X9K2-AM7P-4QR3. Apply it at udemy.com/redeem during checkout. Applies to any eligible course up to €20.', 2000, 'https://cdn.careers.tufts.edu/wp-content/uploads/sites/100/2021/09/udemy.png', TRUE, 'voucher');
INSERT INTO rewards (reward_id, reward_name, reward_description, access_link, access_info, cost_points, img_url, is_active, reward_category) VALUES (15, 'AWS Solutions Architect — Exam Voucher', 'Voucher covering the AWS Solutions Architect Associate (SAA-C03) certification exam fee. Approximate value: $150 USD.', 'https://aws.amazon.com/certification/', 'Your AWS exam voucher code is: AWS-V3QT-N8KX-24MR. Schedule your SAA-C03 exam at aws.training and enter this code at checkout. Valid for 12 months.', 15000, 'https://certvouchers.com/wp-content/uploads/2025/03/aws-solutions-architect-associate-800x407.png', TRUE, 'voucher');
INSERT INTO rewards (reward_id, reward_name, reward_description, access_link, access_info, cost_points, img_url, is_active, reward_category) VALUES (16, 'Exclusive Title: Tech Pioneer', 'Unlock the special "Tech Pioneer" title on your profile. Show that you are among the first to earn store rewards on the platform.', NULL, 'Your title will be applied to your profile automatically within 24 hours.', 300, 'https://cstkpxvilglcavmerctj.supabase.co/storage/v1/object/public/public-assets/structure/rewards/e099ad55-e078-419f-a420-74c69ed2d5f0/teste_1782520803239.png', TRUE, 'title');
INSERT INTO rewards (reward_id, reward_name, reward_description, access_link, access_info, cost_points, is_active, reward_category) VALUES (17, 'Exclusive Title: Innovation Leader', 'Unlock the exclusive "Innovation Leader" title on your profile. A symbol of excellence and leadership in technology innovation.', NULL, 'Your title will be applied to your profile automatically within 24 hours.', 600, TRUE, 'title');
INSERT INTO rewards (reward_id, reward_name, reward_description, access_link, access_info, cost_points, img_url, is_active, reward_category) VALUES (18, 'Mechanical Keyboard — Keychron K2 Pro', 'Premium wireless mechanical keyboard with Gateron switches and RGB backlight. Compact 75% layout, ideal for developers.', NULL, 'Our team will contact you via email to arrange delivery to your office location.', 12000, 'https://keychron.pt/cdn/shop/products/Keychron-K2-Pro-QMK-VIA-Wireless-Mechanical-Keyboard-for-Mac-Windows-PBT-keycaps-PCB-screw-in-stabilizer-hot-swappable-red-switch_7f3edd88-59f3-4516-b953-05cdc3d3bece.jpg?v=1750839599&width=1214', TRUE, 'physical');
INSERT INTO rewards (reward_id, reward_name, reward_description, access_link, access_info, cost_points, img_url, is_active, reward_category) VALUES (19, 'Amazon Gift Card — €25', '€25 Amazon gift card. Use it to buy tech books, gadgets, or anything you like.', NULL, 'Your Amazon Gift Card code is: A4MK-78Q2VPN3-X9RT. Redeem it at amazon.com/gc/redeem or enter it at checkout. This is a €25 credit.', 2500, 'https://cdn.startselect.com/production/products/images/c00ad/70976/3185021334.png', TRUE, 'physical');
INSERT INTO rewards (reward_id, reward_name, reward_description, access_link, access_info, cost_points, img_url, is_active, reward_category) VALUES (20, 'LinkedIn Learning — 3 Months', '3-month access to LinkedIn Learning with over 16,000 courses in technology, business, and creativity.', 'https://www.linkedin.com/learning/', 'Your LinkedIn Learning activation code is: LKL3-9X2K-AM4P-7QR3. Enter it at linkedin.com/learning/redeem to activate your 3-month subscription.', 9000, 'https://media.licdn.com/dms/image/v2/D560DAQHQo1Rkga0thQ/learning-public-crop_288_512/B56ZhkBKvmG0AM-/0/1754024685292?e=2147483647&v=beta&t=SNAz9-FAx8PcHFfLoBuhPql8ZwZi-YrGtSDg4_PKnAs', TRUE, 'subscription');
